using System.Text.Json;
using Connapse.Eval.Statistics;
using FluentAssertions;

namespace Connapse.Eval.Tests.Statistics;

/// <summary>
/// Checks the statistics ports against values produced by the libraries they were ported from
/// (Fixtures/stats/expected.json, regenerated by generate_expected.py).
/// </summary>
[Trait("Category", "Unit")]
public class ReferenceImplementationTests
{
    private static readonly JsonElement Expected = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "stats", "expected.json"))).RootElement;

    private static double[] Doubles(JsonElement array) => array.EnumerateArray().Select(e => e.GetDouble()).ToArray();

    public static TheoryData<int> HolmCases => Cases("holm");

    public static TheoryData<int> PermutationCases => Cases("permutation_exact");

    public static TheoryData<int> BcaCases => Cases("bca");

    private static TheoryData<int> Cases(string key)
    {
        TheoryData<int> data = [];
        for (int i = 0; i < Expected.GetProperty(key).GetArrayLength(); i++)
            data.Add(i);
        return data;
    }

    [Theory]
    [MemberData(nameof(HolmCases))]
    public void Adjust_StatsmodelsFixture_MatchesExactly(int index)
    {
        JsonElement fixture = Expected.GetProperty("holm")[index];

        double[] adjusted = Holm.Adjust(Doubles(fixture.GetProperty("p")));

        adjusted.Should().Equal(Doubles(fixture.GetProperty("adjusted")), (a, e) => Math.Abs(a - e) < 1e-15);
    }

    [Theory]
    [MemberData(nameof(PermutationCases))]
    public void PermutationPValue_ExactEnumerationFixture_MatchesScipyExactly(int index)
    {
        JsonElement fixture = Expected.GetProperty("permutation_exact")[index];

        double p = PairedStats.PermutationPValue(Doubles(fixture.GetProperty("d")), PairedStats.DefaultResamples, new Random(1));

        p.Should().BeApproximately(fixture.GetProperty("p").GetDouble(), 1e-15);
    }

    [Fact]
    public void PermutationPValue_RandomizedFixture_AgreesWithinMonteCarloError()
    {
        JsonElement fixture = Expected.GetProperty("permutation_randomized");
        double expected = fixture.GetProperty("p").GetDouble();
        // Different RNGs, so compare within four standard errors of a 10,000-resample estimate.
        double tolerance = 4 * Math.Sqrt(expected * (1 - expected) / PairedStats.DefaultResamples);

        double p = PairedStats.PermutationPValue(Doubles(fixture.GetProperty("d")), PairedStats.DefaultResamples, new Random(PairedStats.DefaultSeed));

        p.Should().BeApproximately(expected, tolerance);
    }

    [Theory]
    [MemberData(nameof(BcaCases))]
    public void BcaInterval_ScipyResamples_ReproducesScipyInterval(int index)
    {
        JsonElement fixture = Expected.GetProperty("bca")[index];
        int[][] resamples = fixture.GetProperty("indices").EnumerateArray()
            .Select(row => row.EnumerateArray().Select(e => e.GetInt32()).ToArray())
            .ToArray();

        (double low, double high) = PairedStats.BcaInterval(Doubles(fixture.GetProperty("d")), resamples, 0.95);

        low.Should().BeApproximately(fixture.GetProperty("low").GetDouble(), 1e-12);
        high.Should().BeApproximately(fixture.GetProperty("high").GetDouble(), 1e-12);
    }
}
